// SecureNet v1.1 - classify an Uptime Kuma webhook event (B5, B7)
// Kuma sends: {msg, monitor_code, monitor_name, status}; status is Kuma's heartbeat
// status (0 = DOWN, 1 = UP, -1 = no heartbeat, e.g. the "Test" button).

// Containers n8n may restart through the socket proxy (S2: list + restart only).
// n8n and uptime-kuma are deliberately absent: n8n must never restart itself (B6),
// and Kuma already alerts on its own through its direct Telegram notification (B15).
const RESTARTABLE = { HOMEPAGE: 'homepage', PORTAINER: 'portainer', NEXTCLOUD: 'nextcloud' };
// Monitored but not restartable from PC2 (Pi-hole is bare metal on PC1): alert only.
const ALERT_ONLY = { PIHOLE: 'Pi-hole runs on PC1 (bare metal), not in Docker on PC2' };

// De-duplication key for the next node (Remove Duplicates keeps its history in n8n's DB).
// Same monitor + same state inside the same time window = duplicate.
// (Workflow static data is not persisted from Code nodes running in n8n 2.x task runners,
//  which is why the v1 de-duplication never dropped anything.)
const WINDOW = { DOWN: 120, UP: 60 };
const nowSec = Math.floor(Date.now() / 1000);

const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? {};
  const msg = String(b.msg ?? '').trim();
  const monitorCode = String(b.monitor_code ?? '').trim().toUpperCase();
  const hb = Number(b.status);
  const ts = new Date().toISOString();

  let status = 'UNKNOWN';
  if (hb === 0 || /\[\s*🔴\s*down\s*\]/i.test(msg)) status = 'DOWN';
  else if (hb === 1 || /\[\s*(✅|🟢)\s*up\s*\]/i.test(msg)) status = 'UP';

  const nameFromMsg = (msg.match(/^\s*\[([^\]]+)\]/) || [])[1];
  const monitorName = String(b.monitor_name || nameFromMsg || monitorCode || 'unknown').trim();
  const container = RESTARTABLE[monitorCode] ?? null;

  let action, reason;
  if (!monitorCode || !msg) { action = 'INVALID'; reason = 'Missing msg or monitor_code'; }
  else if (status === 'UNKNOWN') { action = 'INFO'; reason = 'Message without a DOWN/UP state (e.g. Kuma test)'; }
  else if (status === 'UP') { action = 'RECOVERED'; reason = 'ok'; }
  else if (container) { action = 'RESTART'; reason = 'ok'; }
  else { action = 'ALERT'; reason = ALERT_ONLY[monitorCode] ?? `No container mapped for monitor_code=${monitorCode}`; }

  const dedupeKey = (status === 'DOWN' || status === 'UP')
    ? `${monitorCode}|${status}|${Math.floor(nowSec / WINDOW[status])}`
    : `${action}|${ts}|${Math.random()}`;          // INFO / INVALID are never de-duplicated

  out.push({ json: { action, status, reason, monitorCode, monitorName, container, msg, ts, dedupeKey } });
}
return out;

// One message per event; restart outcome comes from the HTTP node (B5, B14)
const ev = $('Drop duplicates').item.json;
let restart = null;
if (ev.action === 'RESTART') {
  if ($json.error) {
    const e = $json.error;
    restart = `❌ Reinicio FALLIDO vía socket proxy: ${typeof e === 'string' ? e : (e.message ?? JSON.stringify(e))}`;
  } else {
    restart = `🔁 Contenedor "${ev.container}" reiniciado vía socket proxy (HTTP ${$json.statusCode ?? '2xx'})`;
  }
}
const L = [];
if (ev.action === 'RESTART' || ev.action === 'ALERT') {
  L.push('🚨 SecureNet | SERVICIO CAÍDO', '',
         `🛰️ Servicio: ${ev.monitorName}`, `🆔 Monitor: ${ev.monitorCode}`);
  if (ev.container) L.push(`📦 Contenedor: ${ev.container}`);
  L.push(`🕒 ${ev.ts}`, '', `📩 Uptime Kuma: ${ev.msg}`, '',
         restart ?? `⚠️ Sin reinicio automático: ${ev.reason}`);
} else if (ev.action === 'RECOVERED') {
  L.push('✅ SecureNet | SERVICIO RECUPERADO', '',
         `🛰️ Servicio: ${ev.monitorName}`, `🆔 Monitor: ${ev.monitorCode}`,
         `🕒 ${ev.ts}`, '', `📩 Uptime Kuma: ${ev.msg}`);
} else if (ev.action === 'INFO') {
  L.push('ℹ️ SecureNet | Aviso de Uptime Kuma sin estado', '',
         `🆔 Monitor: ${ev.monitorCode}`, `📩 ${ev.msg}`);
} else {
  L.push('❓ SecureNet | Evento no reconocido en kuma-alert', '', `Motivo: ${ev.reason}`);
}
return { json: { ...ev, restart, text: L.join('\n') } };

// Shared event log for the daily report (B3): one JSON line per DOWN
return $input.all()
  .filter(i => i.json.status === 'DOWN')
  .map(i => ({ json: { line: JSON.stringify({ ts: i.json.ts, type: 'kuma_down',
                                               service: i.json.monitorName, code: i.json.monitorCode }) + '\n' } }));
